// Ziffr -> Microsoft To Do: checks the signature, drops repeats, own echoes and old news, and decides what to do.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on a self-hosted n8n.
const crypto = require('crypto');
const SYSTEM = 'microsoft-todo';
const TASKS = (res) => (res.value || []).map((t) => ({ id: t.id, title: t.title, done: t.status === 'completed', notes: (t.body && t.body.content) || '', url: 'https://to-do.live.com/tasks/id/' + t.id + '/details' }));
const TASK = (t) => ({ id: t.id, url: 'https://to-do.live.com/tasks/id/' + t.id + '/details' });
const DUE = (due) => (due ? { dateTime: due + 'T00:00:00.0000000', timeZone: 'UTC' } : null);
const STATE = (open) => (open ? 'notStarted' : 'completed');
const createBody = (title, notes, due, open) => { const b = { title, body: { content: notes, contentType: 'text' }, status: STATE(open) }; if (due) b.dueDateTime = DUE(due); return b; };
const patchBody = (title, due, open) => ({ title, dueDateTime: DUE(due), status: STATE(open) });
const closeBody = () => ({ status: 'completed' });
const input = $input.first().json;
const headers = Object.fromEntries(Object.entries(input.headers || {}).map(([k, v]) => [k.toLowerCase(), String(v)]));
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const out = (httpStatus, rest = {}) => [{ json: { httpStatus, action: 'none', ...rest } }];

// 1. The signature, over the raw body, within five minutes; a secret replaced in the last 24 hours may sign too (oldSecret).
const secrets = [input.secret, input.oldSecret].filter((s) => s && !String(s).startsWith('REPLACE'));
const timestamp = headers['x-ziffr-timestamp'] || '';
const given = (headers['x-ziffr-signature'] || '').split(',').map((h) => h.trim()).filter((h) => /^sha256=[0-9a-f]{64}$/.test(h));
let signed = /^\d{1,12}$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
let match = false;
for (const secret of secrets) {
  const expected = Buffer.from('sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex'));
  for (const g of given) if (g.length === expected.length && crypto.timingSafeEqual(Buffer.from(g), expected)) match = true;
}
if (!signed || !match) return out(401);

let event;
try { event = JSON.parse(raw); } catch (e) { return out(400); }
const d = event && event.data;
if (!event || typeof event.type !== 'string' || !event.type.startsWith('action.') || !d || typeof d.ref !== 'string') return out(200);

// 2. Once per delivery: Ziffr sends at least once. Static data only lasts while the workflow is active.
const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
state.latest = state.latest || {};
const now = Date.now();
for (const [k, t] of Object.entries(state.seen)) if (now - t > 86400000) delete state.seen[k];
for (const [k, v] of Object.entries(state.latest)) if (now - v.t > 30 * 86400000) delete state.latest[k];
const delivery = headers['x-ziffr-delivery'] || event.id;
if (state.seen[delivery]) return out(200, { why: 'repeat' });
state.seen[delivery] = now;

// 3. Not our own echo, only Tasks, only the newest news per Action.
if (d.source && d.source.type === 'webhook' && d.source.webhook_id === input.webhookId) return out(200, { why: 'echo' });
if (d.kind !== 'task') return out(200, { why: 'question' });
const seenUpdate = state.latest[d.ref];
if (seenUpdate && Date.parse(d.updated_at) < Date.parse(seenUpdate.u)) return out(200, { why: 'older' });
state.latest[d.ref] = { u: d.updated_at, t: now };

// 4. What to do. A redacted message has no title: the task says what it is and links back.
const link = (d.external_ids || []).find((e) => e.system === SYSTEM);
const open = d.status === 'open';
const title = d.redacted ? 'A Ziffr task for you (' + d.ref + ')' : String(d.title || d.ref);
const notes = ['Ziffr ref: ' + d.ref, d.link, !d.redacted && d.metric ? 'Metric: ' + d.metric.name : null, !d.redacted && d.asker ? 'Asked by: ' + d.asker.name : null].filter(Boolean).join('\n');
const base = { ref: d.ref };
if (event.type === 'action.done') return link ? out(200, { ...base, action: 'patch', taskId: link.external_id, patchBody: closeBody() }) : out(200, { why: 'not linked' });
if (event.type === 'action.created' || event.type === 'action.updated') {
  if (link) return out(200, { ...base, action: 'patch', taskId: link.external_id, patchBody: patchBody(title, d.due, open) });
  return open ? out(200, { ...base, action: 'create', createBody: createBody(title, notes, d.due, open) }) : out(200, { why: 'closed and not linked' });
}
return out(200, { why: 'nothing to do' });

// A first event: is there a task with this ref in its notes already (a retry, a lost link)? Then link that one.
const SYSTEM = 'microsoft-todo';
const TASKS = (res) => (res.value || []).map((t) => ({ id: t.id, title: t.title, done: t.status === 'completed', notes: (t.body && t.body.content) || '', url: 'https://to-do.live.com/tasks/id/' + t.id + '/details' }));
const TASK = (t) => ({ id: t.id, url: 'https://to-do.live.com/tasks/id/' + t.id + '/details' });
const DUE = (due) => (due ? { dateTime: due + 'T00:00:00.0000000', timeZone: 'UTC' } : null);
const STATE = (open) => (open ? 'notStarted' : 'completed');
const createBody = (title, notes, due, open) => { const b = { title, body: { content: notes, contentType: 'text' }, status: STATE(open) }; if (due) b.dueDateTime = DUE(due); return b; };
const patchBody = (title, due, open) => ({ title, dueDateTime: DUE(due), status: STATE(open) });
const closeBody = () => ({ status: 'completed' });
const v = $('Verify and filter').first().json;
const found = TASKS($input.first().json).find((t) => new RegExp('Ziffr ref: ' + v.ref + '(\\s|$)').test(t.notes));
return [{ json: { ...v, exists: !!found, taskId: found ? found.id : undefined, taskUrl: found ? found.url : undefined } }];

// Tells Ziffr which task this Action is, so every later event carries it in external_ids.
const SYSTEM = 'microsoft-todo';
const TASKS = (res) => (res.value || []).map((t) => ({ id: t.id, title: t.title, done: t.status === 'completed', notes: (t.body && t.body.content) || '', url: 'https://to-do.live.com/tasks/id/' + t.id + '/details' }));
const TASK = (t) => ({ id: t.id, url: 'https://to-do.live.com/tasks/id/' + t.id + '/details' });
const DUE = (due) => (due ? { dateTime: due + 'T00:00:00.0000000', timeZone: 'UTC' } : null);
const STATE = (open) => (open ? 'notStarted' : 'completed');
const createBody = (title, notes, due, open) => { const b = { title, body: { content: notes, contentType: 'text' }, status: STATE(open) }; if (due) b.dueDateTime = DUE(due); return b; };
const patchBody = (title, due, open) => ({ title, dueDateTime: DUE(due), status: STATE(open) });
const closeBody = () => ({ status: 'completed' });
const v = $('Verify and filter').first().json;
const j = $input.first().json;
const t = j.exists ? { id: j.taskId, url: j.taskUrl } : TASK(j);
return [{ json: { ziffr: { op: 'link', ref: v.ref, system: SYSTEM, external_id: t.id, url: t.url } } }];

// Signs the request exactly as Ziffr signs its messages: HMAC-SHA256 of "<timestamp>.<raw body>" with the Webhook's secret.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on a self-hosted n8n.
const crypto = require('crypto');
const cfg = $('Settings').first().json;
const base = String(cfg.ziffrUrl).replace(/\/+$/, '');
return $input.all().map((item) => {
  const body = JSON.stringify(item.json.ziffr);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'sha256=' + crypto.createHmac('sha256', cfg.secret).update(timestamp + '.' + body).digest('hex');
  return { json: { url: base + '/api/webhooks/' + encodeURIComponent(cfg.webhookId) + '/in', body, timestamp, signature, op: item.json.ziffr.op, ref: item.json.ziffr.ref, text: item.json.ziffr.text } };
});
